def best_circular_selection(values: list[int], k: int) -> int:
    """
    Return the maximum sum of `k` non-adjacent elements chosen from a circular list `values`.
    Raises ValueError if no valid selection of size `k` exists.
    """
    if k < 0:
        raise ValueError("k must be non-negative")
    if k == 0:
        return 0

    n = len(values)
    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError("Cannot select more than 1 element from a list of length 1")

    if k > n // 2:
        raise ValueError(f"Cannot select {k} non-adjacent elements from a circle of length {n}")

    neg_inf = -10**15

    def best_linear(arr: list[int], count: int) -> int:
        if count == 0:
            return 0
        m = len(arr)
        if count > (m + 1) // 2:
            return neg_inf

        prev2 = [0] + [neg_inf] * count
        prev1 = [0] + [neg_inf] * count

        for i, val in enumerate(arr):
            limit = min(count, (i + 2) // 2)
            curr = prev1[:]
            for j in range(1, limit + 1):
                candidate = prev2[j - 1] + val
                if candidate > curr[j]:
                    curr[j] = candidate
            prev2, prev1 = prev1, curr

        return prev1[count]

    # Case 1: Element at index 0 is NOT chosen -> choose k elements from values[1:]
    option_exclude_first = best_linear(values[1:], k)

    # Case 2: Element at index 0 IS chosen -> indices 1 and n-1 cannot be chosen
    option_include_first = values[0] + best_linear(values[2 : n - 1], k - 1)

    return max(option_exclude_first, option_include_first)

def smallest_balanced(s: str) -> str:
    """Return the lexicographically smallest balanced string formed by replacing '?'
    with '(' or ')'. Raises ValueError if no valid replacement exists.
    """
    n = len(s)
    if n % 2 != 0:
        raise ValueError("Odd-length strings cannot be balanced.")

    half = n // 2
    open_needed = half - s.count('(')
    close_needed = half - s.count(')')

    if open_needed < 0 or close_needed < 0:
        raise ValueError("Too many fixed '(' or ')' characters to balance.")

    result = []
    balance = 0

    for ch in s:
        if ch == '?':
            if open_needed > 0:
                ch = '('
                open_needed -= 1
            else:
                ch = ')'

        if ch == '(':
            balance += 1
        else:
            balance -= 1
            if balance < 0:
                raise ValueError("No balanced replacement exists.")

        result.append(ch)

    return "".join(result)

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)

    order = []
    visiting = set()  # Gray nodes: currently on the active DFS path
    visited = set()   # Black nodes: completely resolved

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(graph[node]):
            visit(dep)
        visiting.remove(node)
        visited.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in visited:
            visit(node)
    return order

import re

_AMOUNT_RE = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")


def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError(f"amount must be a string, got {type(amount).__name__}")

        match = _AMOUNT_RE.fullmatch(amount)
        if match is None:
            raise ValueError(f"invalid amount format: {amount!r}")

        whole, frac = match.groups()
        cents = int(whole) * 100 + (int(frac.ljust(2, "0")) if frac else 0)
        if cents <= 0:
            raise ValueError("amount must be positive")

        sender = tx["from"]
        receiver = tx["to"]
        balances[sender] = balances.get(sender, 0) - cents
        balances[receiver] = balances.get(receiver, 0) + cents

    return balances

def apply_hunks(lines, hunks):
    n = len(lines)
    for start, delete, _ in hunks:
        if start < 0 or delete < 0 or start + delete > n:
            raise ValueError("hunk out of range")

    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        curr = ordered[i]
        if curr[0] == prev[0] or curr[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")

    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

