def merge_settings(defaults, overrides):
    result = copy.deepcopy(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = copy.deepcopy(value)
    return result

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

def purge_expired(sessions, now):
    purged = [sid for sid, expiry in sessions.items() if expiry <= now]
    for sid in purged:
        del sessions[sid]
    return purged

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

