class CountingBag:
    """A multiset (bag) of hashable items with deterministic frequency ordering."""

    def __init__(self) -> None:
        self._counts: dict[Hashable, int] = {}
        self._entry: dict[Hashable, tuple[int, Hashable]] = {}
        self._ver: dict[Hashable, int] = {}
        self._total: int = 0
        self._next_eid: int = 0
        self._next_ver: int = 0
        self._heap: list[tuple[int, int, int, Hashable]] | None = None

    def add(self, item: Hashable) -> int:
        """Add one occurrence of `item` and return its new count."""
        current = self._counts.get(item, 0)
        ver = self._next_ver
        self._next_ver += 1

        if current == 0:
            eid = self._next_eid
            self._next_eid += 1
            canonical = item
            new_count = 1
            self._counts[item] = 1
            self._entry[item] = (eid, canonical)
            self._ver[item] = ver
        else:
            new_count = current + 1
            eid, canonical = self._entry[item]
            self._counts[item] = new_count
            self._ver[item] = ver

        self._total += 1

        if self._heap is not None:
            heapq.heappush(self._heap, (-new_count, eid, ver, canonical))
            self._maybe_compact_heap()

        return new_count

    def discard(self, item: Hashable) -> bool:
        """Remove one occurrence of `item`; return True if removed, False if absent."""
        current = self._counts.get(item, 0)
        if current == 0:
            return False

        self._total -= 1

        if current == 1:
            del self._counts[item]
            del self._entry[item]
            del self._ver[item]
            if self._heap is not None:
                self._maybe_compact_heap()
        else:
            new_count = current - 1
            ver = self._next_ver
            self._next_ver += 1
            eid, canonical = self._entry[item]
            self._counts[item] = new_count
            self._ver[item] = ver
            if self._heap is not None:
                heapq.heappush(self._heap, (-new_count, eid, ver, canonical))
                self._maybe_compact_heap()

        return True

    def count(self, item: Hashable) -> int:
        """Return the current count of `item` (0 if absent)."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Return the total number of occurrences across all items."""
        return self._total

    def distinct(self) -> int:
        """Return the number of distinct items currently present."""
        return len(self._counts)

    def most_common(self, k: int) -> list[tuple[Hashable, int]]:
        """Return up to `k` `(item, count)` pairs ordered by count desc, then entry time asc."""
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0 or not self._counts:
            return []

        n = len(self._counts)
        if k >= n:
            return sorted(self._counts.items(), key=lambda kv: -kv[1])
        if n <= 64 or k * 4 >= n:
            return sorted(self._counts.items(), key=lambda kv: -kv[1])[:k]

        if self._heap is None:
            self._build_heap()
            assert self._heap is not None

        popped: list[tuple[int, int, int, Hashable]] = []
        result: list[tuple[Hashable, int]] = []

        while len(result) < k and self._heap:
            entry = heapq.heappop(self._heap)
            neg_count, _, ver, canonical = entry
            if self._ver.get(canonical) == ver:
                popped.append(entry)
                result.append((canonical, -neg_count))

        for entry in popped:
            heapq.heappush(self._heap, entry)

        return result

    def _build_heap(self) -> None:
        self._heap = [
            (-count, self._entry[item][0], self._ver[item], item)
            for item, count in self._counts.items()
        ]
        heapq.heapify(self._heap)

    def _maybe_compact_heap(self) -> None:
        if self._heap is not None and len(self._heap) > 2 * len(self._counts) + 1024:
            self._build_heap()

