class TTLCache:
    """Fixed-capacity LRU cache with optional per-entry TTL and explicit clock."""

    def __init__(self, capacity: int) -> None:
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self._capacity: int = capacity
        # Maps key -> (value, expires_at, seq) ordered from LRU to MRU
        self._data: OrderedDict[Any, tuple[Any, int | float | None, int]] = OrderedDict()
        # Min-heap of (expires_at, seq, key); seq breaks ties without comparing keys
        self._heap: list[tuple[int | float, int, Any]] = []
        self._seq: int = 0

        self._hits: int = 0
        self._misses: int = 0
        self._evictions: int = 0
        self._expirations: int = 0

    def _purge(self, now: int | float) -> None:
        """Remove all entries whose expiration time is <= now."""
        while self._heap and self._heap[0][0] <= now:
            _, seq, key = heapq.heappop(self._heap)
            entry = self._data.get(key)
            if entry is not None and entry[2] == seq:
                del self._data[key]
                self._expirations += 1

    def _compact_heap_if_needed(self) -> None:
        """Rebuild the expiration heap if stale entries accumulate."""
        if len(self._heap) > 2 * self._capacity + 64:
            self._heap = [
                (expires_at, seq, key)
                for key, (_, expires_at, seq) in self._data.items()
                if expires_at is not None
            ]
            heapq.heapify(self._heap)

    def put(
        self,
        key: Any,
        value: Any,
        now: int | float,
        ttl: int | float | None = None,
    ) -> None:
        if ttl is not None:
            if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or ttl <= 0:
                raise ValueError("ttl must be a positive number or None")

        self._purge(now)

        if key in self._data:
            self._data.move_to_end(key)
        elif len(self._data) >= self._capacity:
            self._data.popitem(last=False)
            self._evictions += 1

        self._seq += 1
        expires_at = None if ttl is None else now + ttl
        self._data[key] = (value, expires_at, self._seq)

        if expires_at is not None:
            heapq.heappush(self._heap, (expires_at, self._seq, key))
            self._compact_heap_if_needed()

    def get(self, key: Any, now: int | float) -> Any:
        self._purge(now)

        if key in self._data:
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key][0]

        self._misses += 1
        return None

    def stats(self) -> dict[str, int]:
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self) -> int:
        return len(self._data)

