from typing import Hashable


class Leaderboard:
    """Tracks players' best scores and standard competition rankings."""

    def __init__(self) -> None:
        # Maps player -> (best_score, sequence_number)
        self._players: dict[Hashable, tuple[int, int]] = {}
        # Maintained sorted by (-score, sequence_number, player)
        self._sorted: list[tuple[int, int, Hashable]] = []
        self._seq: int = 0

    def submit(self, player: Hashable, score: int) -> bool:
        """Record a score attempt; return True iff it sets a new personal best."""
        if player in self._players:
            old_score, old_seq = self._players[player]
            if score <= old_score:
                return False
            # Unique (old_score, old_seq) locates the exact entry without comparing `player`
            idx = bisect_left(self._sorted, (-old_score, old_seq))
            self._sorted.pop(idx)

        seq = self._seq
        self._seq += 1
        self._players[player] = (score, seq)
        insort(self._sorted, (-score, seq, player))
        return True

    def best(self, player: Hashable) -> int:
        """Return the player's highest submitted score, or raise KeyError."""
        if player not in self._players:
            raise KeyError(player)
        return self._players[player][0]

    def rank(self, player: Hashable) -> int:
        """Return 1 + count of players with a strictly higher best score."""
        if player not in self._players:
            raise KeyError(player)
        score = self._players[player][0]
        # Since all sequence numbers are >= 0, (-score, -1) lands right before
        # the earliest player with `score`, giving the exact count of higher scores.
        return bisect_left(self._sorted, (-score, -1)) + 1

    def top(self, k: int) -> list[tuple[Hashable, int]]:
        """Return up to `k` top (player, best) pairs ordered by rank and tie-breaker."""
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0:
            return []
        return [(player, -neg_score) for neg_score, _, player in self._sorted[:k]]

    def player_count(self) -> int:
        """Return the total number of distinct players seen."""
        return len(self._players)

