class IntervalSet:
    """A normalized set of integers represented as disjoint, non-adjacent half-open intervals [lo, hi)."""

    def __init__(self) -> None:
        # Flat sorted list of endpoints [lo_0, hi_0, lo_1, hi_1, ...]
        # Invariant: _pts[0] < _pts[1] < _pts[2] < ... and len(_pts) is even.
        self._pts: list[int] = []
        self._total: int = 0

    @staticmethod
    def _validate_interval(lo: int, hi: int) -> None:
        if (
            isinstance(lo, bool)
            or isinstance(hi, bool)
            or not (isinstance(lo, int) and isinstance(hi, int))
        ):
            raise TypeError("Interval endpoints must be integers")
        if lo >= hi:
            raise ValueError(f"Expected lo < hi, got [{lo}, {hi})")

    @staticmethod
    def _slice_contribution(seq: list[int], start_idx: int) -> int:
        if start_idx % 2 == 0:
            return sum(seq[1::2]) - sum(seq[0::2])
        return sum(seq[0::2]) - sum(seq[1::2])

    def _replace(self, i: int, j: int, new_pts: list[int]) -> None:
        old_pts = self._pts[i:j]
        self._total += self._slice_contribution(new_pts, i) - self._slice_contribution(old_pts, i)
        self._pts[i:j] = new_pts

    def add(self, lo: int, hi: int) -> None:
        """Cover every integer in [lo, hi), coalescing overlapping and adjacent intervals."""
        self._validate_interval(lo, hi)
        i = bisect_left(self._pts, lo)
        j = bisect_right(self._pts, hi)

        new_pts: list[int] = []
        if i % 2 == 0:
            new_pts.append(lo)
        if j % 2 == 0:
            new_pts.append(hi)

        self._replace(i, j, new_pts)

    def remove(self, lo: int, hi: int) -> None:
        """Uncover every integer in [lo, hi)."""
        self._validate_interval(lo, hi)
        i = bisect_left(self._pts, lo)
        j = bisect_right(self._pts, hi)

        new_pts: list[int] = []
        if i % 2 == 1:
            new_pts.append(lo)
        if j % 2 == 1:
            new_pts.append(hi)

        self._replace(i, j, new_pts)

    def contains(self, x: int) -> bool:
        """Return whether the integer x is covered."""
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("x must be an integer")
        return bisect_right(self._pts, x) % 2 == 1

    def total(self) -> int:
        """Return the total number of covered integers."""
        return self._total

    def intervals(self) -> list[tuple[int, int]]:
        """Return the covered set as a normalized sorted list of (lo, hi) tuples."""
        pts = self._pts
        return [(pts[k], pts[k + 1]) for k in range(0, len(pts), 2)]

    def gaps(self, lo: int, hi: int) -> list[tuple[int, int]]:
        """Return the maximal uncovered sub-intervals of [lo, hi) as sorted (a, b) tuples."""
        self._validate_interval(lo, hi)
        i = bisect_right(self._pts, lo)
        j = bisect_left(self._pts, hi)

        gap_pts: list[int] = []
        if i % 2 == 0:
            gap_pts.append(lo)
        gap_pts.extend(self._pts[i:j])
        if j % 2 == 0:
            gap_pts.append(hi)

        return [(gap_pts[k], gap_pts[k + 1]) for k in range(0, len(gap_pts), 2)]

    def __contains__(self, x: int) -> bool:
        return self.contains(x)

    def __repr__(self) -> str:
        return f"IntervalSet({self.intervals()!r})"

