class UndoStack:
    """A LIFO stack supporting undo of mutating operations (push and pop)."""

    def __init__(self) -> None:
        self._stack: list[Any] = []
        # History entries are either ("push",) or ("pop", value)
        self._history: list[tuple[Any, ...]] = []

    def push(self, x: Any) -> None:
        """Push x onto the top of the stack."""
        self._stack.append(x)
        self._history.append(("push",))

    def pop(self) -> Any:
        """Remove and return the top value. Raises IndexError if empty."""
        if not self._stack:
            raise IndexError("pop from empty UndoStack")
        val = self._stack.pop()
        self._history.append(("pop", val))
        return val

    def peek(self) -> Any:
        """Return the top value without removing it. Raises IndexError if empty."""
        if not self._stack:
            raise IndexError("peek from empty UndoStack")
        return self._stack[-1]

    def undo(self) -> None:
        """Reverse the most recent un-undone push or pop. Raises RuntimeError if none."""
        if not self._history:
            raise RuntimeError("nothing left to undo")
        entry = self._history.pop()
        if entry[0] == "push":
            self._stack.pop()
        else:
            self._stack.append(entry[1])

    def __len__(self) -> int:
        """Return the number of values currently on the stack."""
        return len(self._stack)

from typing import Any, Optional

_MISSING = object()
_HASH_MASK = (1 << 64) - 1
_POPCOUNT = int.bit_count if hasattr(int, "bit_count") else lambda x: bin(x).count("1")


class _Leaf:
    __slots__ = ("h", "pairs")

    def __init__(self, h: int, pairs: tuple[tuple[Any, Any], ...]) -> None:
        self.h = h
        self.pairs = pairs


class _Branch:
    __slots__ = ("bitmap", "children")

    def __init__(self, bitmap: int, children: tuple[Any, ...]) -> None:
        self.bitmap = bitmap
        self.children = children


_Node = Optional[_Leaf | _Branch]


def _lookup(node: _Node, h: int, key: Any) -> Any:
    shift = 0
    while isinstance(node, _Branch):
        bit = 1 << ((h >> shift) & 0x1F)
        if not (node.bitmap & bit):
            return _MISSING
        idx = _POPCOUNT(node.bitmap & (bit - 1))
        node = node.children[idx]
        shift += 5

    if node is None or node.h != h:
        return _MISSING

    for k, v in node.pairs:
        if k == key:
            return v
    return _MISSING


def _merge_leaves(leaf1: _Leaf, leaf2: _Leaf, shift: int) -> _Branch:
    b1 = (leaf1.h >> shift) & 0x1F
    b2 = (leaf2.h >> shift) & 0x1F
    if b1 == b2:
        child = _merge_leaves(leaf1, leaf2, shift + 5)
        return _Branch(1 << b1, (child,))
    children = (leaf1, leaf2) if b1 < b2 else (leaf2, leaf1)
    return _Branch((1 << b1) | (1 << b2), children)


def _insert(node: _Node, h: int, key: Any, value: Any, shift: int) -> _Leaf | _Branch:
    if node is None:
        return _Leaf(h, ((key, value),))

    if isinstance(node, _Leaf):
        if node.h == h:
            for i, (k, v) in enumerate(node.pairs):
                if k == key:
                    if v is value:
                        return node
                    new_pairs = node.pairs[:i] + ((k, value),) + node.pairs[i + 1 :]
                    return _Leaf(h, new_pairs)
            return _Leaf(h, node.pairs + ((key, value),))
        return _merge_leaves(node, _Leaf(h, ((key, value),)), shift)

    bit = 1 << ((h >> shift) & 0x1F)
    idx = _POPCOUNT(node.bitmap & (bit - 1))
    if node.bitmap & bit:
        child = node.children[idx]
        new_child = _insert(child, h, key, value, shift + 5)
        if new_child is child:
            return node
        new_children = node.children[:idx] + (new_child,) + node.children[idx + 1 :]
        return _Branch(node.bitmap, new_children)

    new_child = _Leaf(h, ((key, value),))
    new_children = node.children[:idx] + (new_child,) + node.children[idx:]
    return _Branch(node.bitmap | bit, new_children)


def _remove(node: _Node, h: int, key: Any, shift: int) -> _Node:
    if node is None:
        raise KeyError(key)

    if isinstance(node, _Leaf):
        if node.h != h:
            raise KeyError(key)
        for i, (k, _) in enumerate(node.pairs):
            if k == key:
                if len(node.pairs) == 1:
                    return None
                return _Leaf(h, node.pairs[:i] + node.pairs[i + 1 :])
        raise KeyError(key)

    bit = 1 << ((h >> shift) & 0x1F)
    if not (node.bitmap & bit):
        raise KeyError(key)

    idx = _POPCOUNT(node.bitmap & (bit - 1))
    new_child = _remove(node.children[idx], h, key, shift + 5)

    if new_child is None:
        new_bitmap = node.bitmap ^ bit
        if new_bitmap == 0:
            return None
        new_children = node.children[:idx] + node.children[idx + 1 :]
        if len(new_children) == 1 and isinstance(new_children[0], _Leaf):
            return new_children[0]
        return _Branch(new_bitmap, new_children)

    if len(node.children) == 1 and isinstance(new_child, _Leaf):
        return new_child

    new_children = node.children[:idx] + (new_child,) + node.children[idx + 1 :]
    return _Branch(node.bitmap, new_children)


class VersionedKV:
    """A key-value store supporting immutable commit snapshots, point-in-time reads, and rollback."""

    def __init__(self) -> None:
        self._working: _Node = None
        self._snapshots: list[_Node] = []

    def set(self, key: Any, value: Any) -> None:
        """Write key/value to the working state."""
        h = hash(key) & _HASH_MASK
        self._working = _insert(self._working, h, key, value, 0)

    def delete(self, key: Any) -> None:
        """Remove key from the working state, raising KeyError if absent."""
        h = hash(key) & _HASH_MASK
        self._working = _remove(self._working, h, key, 0)

    def get(self, key: Any) -> Any:
        """Read key from the working state, raising KeyError if absent."""
        h = hash(key) & _HASH_MASK
        val = _lookup(self._working, h, key)
        if val is _MISSING:
            raise KeyError(key)
        return val

    def has(self, key: Any) -> bool:
        """Return True if key is present in the working state."""
        h = hash(key) & _HASH_MASK
        return _lookup(self._working, h, key) is not _MISSING

    def commit(self) -> int:
        """Snapshot the current working state and return the new version number."""
        self._snapshots.append(self._working)
        return len(self._snapshots)

    def latest(self) -> int:
        """Return the number of commits made so far."""
        return len(self._snapshots)

    def get_at(self, key: Any, version: int) -> Any:
        """Read key from snapshot `version`."""
        if (
            isinstance(version, bool)
            or not isinstance(version, int)
            or not (1 <= version <= len(self._snapshots))
        ):
            raise ValueError(f"Version must be an integer in 1..{len(self._snapshots)}, got {version!r}")

        h = hash(key) & _HASH_MASK
        val = _lookup(self._snapshots[version - 1], h, key)
        if val is _MISSING:
            raise KeyError(key)
        return val

    def rollback(self, version: int) -> None:
        """Replace the working state with snapshot `version` (0 = empty state)."""
        if (
            isinstance(version, bool)
            or not isinstance(version, int)
            or not (0 <= version <= len(self._snapshots))
        ):
            raise ValueError(f"Version must be an integer in 0..{len(self._snapshots)}, got {version!r}")

        self._working = None if version == 0 else self._snapshots[version - 1]

import unicodedata

COMBINING_CATEGORIES = frozenset(("Mn", "Mc", "Me"))


def truncate_display(s: str, width: int) -> str:
    """Truncate a string to a maximum number of user-perceived character units.

    Combining marks ('Mn', 'Mc', 'Me') attach to the preceding character unit
    and add zero width, unless they appear at the very start of the string, in
    which case the first mark begins an initial unit and consecutive marks join it.
    """
    if width < 0:
        raise ValueError(f"width must be non-negative, got {width}")
    if width == 0 or not s:
        return ""

    units = 0
    for i, ch in enumerate(s):
        is_combining = unicodedata.category(ch) in COMBINING_CATEGORIES
        if i == 0 or not is_combining:
            if units == width:
                return s[:i]
            units += 1

    return s

def chunk_evenly(items, n: int) -> list[list]:
    """Split an iterable into n contiguous chunks whose lengths differ by at most 1."""
    if n < 1:
        raise ValueError(f"n must be at least 1, got {n}")

    elements = list(items)
    quotient, remainder = divmod(len(elements), n)

    return [
        elements[
            i * quotient + min(i, remainder)
            : (i + 1) * quotient + min(i + 1, remainder)
        ]
        for i in range(n)
    ]

import math


def kth_root_floor(n: int, k: int) -> int:
    """Return the largest integer r >= 0 such that r ** k <= n."""
    if n < 0:
        raise ValueError("n must be >= 0")
    if k < 1:
        raise ValueError("k must be >= 1")

    if n <= 1 or k == 1:
        return n
    if k == 2:
        return math.isqrt(n)

    bit_len = n.bit_length()
    # Since n < 2**bit_len, if k >= bit_len then 2**k >= 2**bit_len > n,
    # so the floor of the k-th root must be 1.
    if k >= bit_len:
        return 1

    # From 2**(bit_len - 1) <= n < 2**bit_len, we get tight power-of-two bounds:
    # low**k <= 2**(bit_len - 1) <= n < 2**bit_len <= high**k
    low = 1 << ((bit_len - 1) // k)
    high = low << 1

    while low + 1 < high:
        mid = (low + high) >> 1
        if mid**k <= n:
            low = mid
        else:
            high = mid

    return low

from fractions import Fraction
import math
from numbers import Integral


def allocate_shares(total: int, weights: list) -> list[int]:
    """Split an integer total into nonnegative integer shares proportional to weights.

    Uses the largest-remainder (Hamilton) method with exact rational arithmetic,
    breaking remainder ties in favor of the lower party index.
    """
    if isinstance(total, bool) or not isinstance(total, Integral) or total < 0:
        raise ValueError("total must be an integer >= 0")
    total = int(total)

    weights_list = list(weights)
    if not weights_list:
        raise ValueError("weights must not be empty")

    frac_weights: list[Fraction] = []
    for w in weights_list:
        if isinstance(w, bool):
            raise ValueError("weights must be numeric values >= 0")
        try:
            if math.isnan(w) or math.isinf(w):
                raise ValueError("weights must be finite numbers")
            fw = Fraction(w)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError("weights must contain finite real numbers") from exc
        if fw < 0:
            raise ValueError("weights must all be >= 0")
        frac_weights.append(fw)

    weight_sum = sum(frac_weights, Fraction(0))
    if weight_sum <= 0:
        raise ValueError("sum of weights must be > 0")

    if total == 0:
        return [0] * len(frac_weights)

    floors: list[int] = []
    remainders: list[Fraction] = []
    for fw in frac_weights:
        quota = (total * fw) / weight_sum
        floor_q = quota.numerator // quota.denominator
        floors.append(floor_q)
        remainders.append(quota - floor_q)

    shortfall = total - sum(floors)
    if shortfall > 0:
        ranked_indices = sorted(
            range(len(frac_weights)),
            key=lambda i: (-remainders[i], i),
        )
        for i in ranked_indices[:shortfall]:
            floors[i] += 1

    return floors

from collections import deque
from typing import Iterator


def round_robin(iterables: list) -> Iterator:
    """Lazily interleave values from a list of iterables in round-robin order."""
    active = deque(iter(it) for it in iterables)
    while active:
        it = active.popleft()
        try:
            value = next(it)
        except StopIteration:
            continue
        active.append(it)
        yield value

def weighted_median(values: list, weights: list) -> float:
    """Return the lower weighted median of values with corresponding weights."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length.")
    if not values:
        raise ValueError("values and weights must not be empty.")

    pairs = []
    total_weight = 0.0
    for v, w in zip(values, weights):
        if w < 0:
            raise ValueError("All weights must be non-negative.")
        if w > 0:
            pairs.append((v, w))
            total_weight += w

    if total_weight <= 0 or not pairs:
        raise ValueError("Sum of weights must be greater than zero.")

    pairs.sort(key=lambda pair: pair[0])

    threshold = total_weight / 2.0 - 1e-9
    cumulative_weight = 0.0
    for v, w in pairs:
        cumulative_weight += w
        if cumulative_weight >= threshold:
            return v

    return pairs[-1][0]

import math


def vector_norm(v: list[float]) -> float:
    """Compute the Euclidean (L2) norm of a vector of floats."""
    max_abs = 0.0
    for x in v:
        if not math.isfinite(x):
            raise ValueError(f"Vector entries must be finite numbers, got {x!r}")
        ax = abs(x)
        if ax > max_abs:
            max_abs = ax

    if max_abs == 0.0:
        return 0.0

    # Scale by an exact power of two so the largest magnitude lies in [0.5, 1.0).
    # ldexp adjusts only the exponent, introducing zero rounding error.
    _, exp = math.frexp(max_abs)
    scaled_sq_sum = math.fsum((s := math.ldexp(x, -exp)) * s for x in v)

    try:
        return math.ldexp(math.sqrt(scaled_sq_sum), exp)
    except OverflowError:
        return math.inf

from heapq import heapify, heappush, heapreplace


def max_bounty(jobs: list[tuple[int, int]], cap: int) -> int:
    """Return the maximum total bounty of unit-time jobs schedulable with slot capacity `cap`."""
    if cap < 1:
        raise ValueError("cap must be at least 1")

    n = len(jobs)
    if n == 0:
        return 0

    # Because m * cap >= n, any job with deadline d >= m can always be placed
    # alongside any valid subset of jobs with earlier deadlines.
    m = (n + cap - 1) // cap
    buckets: list[list[int] | None] = [None] * m
    unconditional_total = 0

    for d, p in jobs:
        if d >= m:
            unconditional_total += p
        else:
            b = buckets[d]
            if b is None:
                buckets[d] = [p]
            else:
                b.append(p)

    # Process deadlines 1 .. m - 1 in ascending order. A subset of jobs is valid
    # iff for every deadline d, at most d * cap jobs have deadline <= d.
    h: list[int] = []
    is_heap = False
    limit = -cap

    for bucket in buckets:
        limit += cap
        if bucket is None:
            continue

        if not is_heap:
            if len(h) + len(bucket) <= limit:
                h.extend(bucket)
                continue

            need = limit - len(h)
            if need > 0:
                h.extend(bucket[:need])
                rest = bucket[need:]
            else:
                rest = bucket

            heapify(h)
            is_heap = True
            min_p = h[0]
            for p in rest:
                if p > min_p:
                    heapreplace(h, p)
                    min_p = h[0]
        else:
            free = limit - len(h)
            if free >= len(bucket):
                for p in bucket:
                    heappush(h, p)
            else:
                if free > 0:
                    for p in bucket[:free]:
                        heappush(h, p)
                    rest = bucket[free:]
                else:
                    rest = bucket

                min_p = h[0]
                for p in rest:
                    if p > min_p:
                        heapreplace(h, p)
                        min_p = h[0]

    return unconditional_total + sum(h)

from itertools import accumulate, islice
import operator


def count_pulses(deltas: list[int], k: int, lo: int, hi: int) -> int:
    """Count contiguous subarrays of `deltas` with length in [lo, hi] and sum divisible by `k`."""
    n = len(deltas)
    if not (1 <= lo <= hi <= n):
        raise ValueError(
            f"Expected 1 <= lo <= hi <= len(deltas), got lo={lo}, hi={hi}, len={n}"
        )

    if k == 1:
        return (hi - lo + 1) * (2 * n + 2 - lo - hi) // 2

    rem = [s % k for s in accumulate(deltas, initial=0)]

    if lo == hi:
        return sum(map(operator.eq, rem, islice(rem, lo, None)))

    ans = 0
    if k <= 2_000_000:
        freq_list = [0] * k
        for r_add, r_q in zip(rem, islice(rem, lo, hi + 1)):
            freq_list[r_add] += 1
            ans += freq_list[r_q]
        for r_rem, r_add, r_q in zip(
            rem, islice(rem, hi - lo + 1, None), islice(rem, hi + 1, None)
        ):
            freq_list[r_rem] -= 1
            freq_list[r_add] += 1
            ans += freq_list[r_q]
    else:
        freq_dict: dict[int, int] = {}
        get = freq_dict.get
        for r_add, r_q in zip(rem, islice(rem, lo, hi + 1)):
            freq_dict[r_add] = get(r_add, 0) + 1
            ans += get(r_q, 0)
        for r_rem, r_add, r_q in zip(
            rem, islice(rem, hi - lo + 1, None), islice(rem, hi + 1, None)
        ):
            freq_dict[r_rem] -= 1
            freq_dict[r_add] = get(r_add, 0) + 1
            ans += get(r_q, 0)

    return ans

from itertools import islice
import random


def longest_echo(s: str) -> int:
    """Return the length of the longest substring occurring at least twice in s."""
    n = len(s)
    distinct = len(set(s))
    if distinct == n:
        return 0
    if distinct == 1:
        return n - 1

    # Since 1 < distinct < n (so n >= 3):
    # - At least one single character repeats, so answer >= 1.
    # - A repeat of length n - 1 would force s[0:n-1] == s[1:n], implying all
    #   characters are equal (distinct == 1), so answer < n - 1.
    lo = 1
    hi = n - 1
    if hi - lo == 1:
        return 1

    mod = (1 << 61) - 1  # Mersenne prime 2^61 - 1
    base = random.randrange(257, mod)

    prefix_hash = [0] * (n + 1)
    h = 0
    for i, byte in enumerate(s.encode("ascii"), 1):
        h = (h * base + byte) % mod
        prefix_hash[i] = h

    def has_repeat(length: int) -> bool:
        base_l = pow(base, length, mod)
        vals = [
            (b - a * base_l) % mod
            for a, b in zip(prefix_hash, islice(prefix_hash, length, None))
        ]
        if len(set(vals)) == len(vals):
            return False

        # Verify exact substring match to eliminate any hash collision risk.
        seen: dict[int, int | list[int]] = {}
        for i, v in enumerate(vals):
            prev = seen.get(v)
            if prev is None:
                seen[v] = i
            elif isinstance(prev, int):
                if s[prev : prev + length] == s[i : i + length]:
                    return True
                seen[v] = [prev, i]
            else:
                for p in prev:
                    if s[p : p + length] == s[i : i + length]:
                        return True
                prev.append(i)
        return False

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if has_repeat(mid):
            lo = mid
        else:
            hi = mid

    return lo

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    summary = {}

    for i, row in enumerate(rows):
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(f"Expected a 3-element tuple at row {i}")

        category, amount, refunded = row

        if not isinstance(category, str) or len(category) == 0:
            raise ValueError(f"Category must be a non-empty str at row {i}")

        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"Amount must be an int or float at row {i}")

        if not (amount >= 0):
            raise ValueError(f"Amount must be >= 0 at row {i}")

        if not isinstance(refunded, bool):
            raise TypeError(f"Refunded must be a bool at row {i}")

        amt_float = float(amount)

        if category not in summary:
            summary[category] = {
                "count": 1,
                "gross": amt_float,
                "net": 0.0 if refunded else amt_float,
                "largest": amt_float,
            }
        else:
            cat_data = summary[category]
            cat_data["count"] += 1
            cat_data["gross"] += amt_float
            if not refunded:
                cat_data["net"] += amt_float
            if amt_float > cat_data["largest"]:
                cat_data["largest"] = amt_float

    return summary

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    if (
        isinstance(low, bool)
        or not isinstance(low, (int, float))
        or isinstance(high, bool)
        or not isinstance(high, (int, float))
    ):
        raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"element at index {i} must be a number")
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)

    return result

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    if max_depth == 0:
        return list(nested)

    result = []
    stack = [(iter(nested), 0)]

    while stack:
        current_iter, depth = stack[-1]
        for item in current_iter:
            if isinstance(item, list) and depth < max_depth:
                stack.append((iter(item), depth + 1))
                break
            result.append(item)
        else:
            stack.pop()

    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")

    if not text or text.isspace():
        raise ValueError("empty duration")

    units = {
        "h": (0, 3600),
        "m": (1, 60),
        "s": (2, 1),
    }

    total_seconds = 0
    last_unit_order = -1
    digit_start = 0

    for i, ch in enumerate(text):
        if "0" <= ch <= "9":
            continue
        if ch in units:
            if i == digit_start:
                raise ValueError("malformed duration: missing digits before unit")
            order, multiplier = units[ch]
            if order <= last_unit_order:
                raise ValueError("malformed duration: invalid unit order or duplicate unit")
            total_seconds += int(text[digit_start:i]) * multiplier
            last_unit_order = order
            digit_start = i + 1
        else:
            raise ValueError("malformed duration: unexpected character")

    if digit_start != len(text) or last_unit_order == -1:
        raise ValueError("malformed duration: trailing digits without unit")

    return total_seconds

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    out = []
    n = len(template)
    i = 0

    while i < n:
        ch = template[i]
        if ch == "{":
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue

            start = i
            j = i + 1
            while j < n and template[j] != "}":
                c = template[j]
                if not (
                    ("A" <= c <= "Z")
                    or ("a" <= c <= "z")
                    or ("0" <= c <= "9")
                    or c == "_"
                ):
                    raise ValueError(
                        "invalid placeholder at position " + str(start)
                    )
                j += 1

            if j == n:
                raise ValueError(
                    "unclosed placeholder at position " + str(start)
                )

            if j == start + 1:
                raise ValueError(
                    "empty placeholder at position " + str(start)
                )

            name = template[start + 1 : j]
            if name not in context:
                raise KeyError(name)

            out.append(str(context[name]))
            i = j + 1

        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))
        else:
            out.append(ch)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")

    stack = []

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"expected str at token {i}")

        if token in ("+", "-", "*", "/"):
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()

            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                quotient = abs(left) // abs(right)
                if (left < 0) ^ (right < 0):
                    quotient = -quotient
                stack.append(quotient)
        else:
            if not token:
                raise ValueError(f"unknown token at token {i}")

            start = 1 if token[0] in ("+", "-") else 0
            if start == len(token):
                raise ValueError(f"unknown token at token {i}")

            digits = token[start:]
            for ch in digits:
                if not ("0" <= ch <= "9"):
                    raise ValueError(f"unknown token at token {i}")

            if len(digits) <= 4000:
                value = int(token)
            else:
                value = 0
                for j in range(0, len(digits), 1000):
                    chunk = digits[j : j + 1000]
                    value = value * (10 ** len(chunk)) + int(chunk)
                if token[0] == "-":
                    value = -value

            stack.append(value)

    if len(stack) > 1:
        raise ValueError("leftover operands")

    return stack[0]

_ASCII_DIGITS = frozenset("0123456789")


def _is_int_literal(segment):
    digits = segment[1:] if segment.startswith("-") else segment
    return bool(digits) and set(digits) <= _ASCII_DIGITS


def _descend(node, segments, pos):
    if pos == len(segments):
        return node

    seg = segments[pos]

    if isinstance(node, dict):
        if seg not in node:
            raise KeyError(seg)
        return _descend(node[seg], segments, pos + 1)

    if isinstance(node, list):
        if not _is_int_literal(seg):
            raise ValueError(f"invalid index: {seg}")
        idx = int(seg)
        if idx < -len(node) or idx >= len(node):
            raise IndexError(f"list index out of range: {seg}")
        return _descend(node[idx], segments, pos + 1)

    raise TypeError(f"cannot descend into {type(node).__name__}")


def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:
        raise ValueError("path contains an empty segment")

    return _descend(data, segments, 0)

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    if k == 0 or len(items) == 0:
        return []

    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1

    n = len(items)
    buckets = [[] for _ in range(n + 1)]
    for val, cnt in counts.items():
        buckets[cnt].append((val, cnt))

    result = []
    for cnt in range(n, 0, -1):
        for pair in buckets[cnt]:
            result.append(pair)
            if len(result) == k:
                return result

    return result
